-- Explicit trend exit v5 migration. Verify no same-named object with a different shape before execution.
CREATE TABLE htx_trend_entry_contract (id BIGINT AUTO_INCREMENT PRIMARY KEY,position_id BIGINT NOT NULL,position_epoch BIGINT NOT NULL,account_id BIGINT NOT NULL,strategy_instance VARCHAR(64) NOT NULL,engine_version VARCHAR(32) NOT NULL,policy_hash CHAR(64) NOT NULL,contract_hash CHAR(64) NOT NULL,structure_id VARCHAR(160) NOT NULL,contract_json MEDIUMTEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uk_trend_entry_contract_epoch(position_id,position_epoch),KEY idx_trend_entry_contract_structure(account_id,structure_id));
CREATE TABLE htx_trend_exit_owner_lease_v5 (scope_key VARCHAR(160) PRIMARY KEY,owner_id VARCHAR(128) NOT NULL,owner_token BIGINT NOT NULL,lease_until DATETIME(3) NOT NULL,renewed_at DATETIME(3) NOT NULL,UNIQUE KEY uk_trend_exit_owner_token(scope_key,owner_token));
CREATE TABLE htx_trend_exit_state_v5 (position_id BIGINT PRIMARY KEY,position_epoch BIGINT NOT NULL,revision BIGINT NOT NULL,contract_id BIGINT NOT NULL,owner_token BIGINT NOT NULL,last_bar_end BIGINT NULL,last_event_key VARCHAR(160) NOT NULL,phase VARCHAR(24) NOT NULL,execution_state VARCHAR(24) NOT NULL,confirmed_remaining_qty DECIMAL(36,18) NOT NULL,state_json MEDIUMTEXT NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY idx_trend_exit_state_phase(phase,updated_at));
CREATE TABLE htx_trend_exit_intent_v5 (id BIGINT AUTO_INCREMENT PRIMARY KEY,decision_key VARCHAR(160) NOT NULL,position_id BIGINT NOT NULL,position_epoch BIGINT NOT NULL,state_revision BIGINT NOT NULL,owner_token BIGINT NOT NULL,client_order_id VARCHAR(64) NOT NULL,target_remaining_qty DECIMAL(36,18) NOT NULL,status VARCHAR(24) NOT NULL,payload_json MEDIUMTEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uk_trend_exit_intent_decision(decision_key),UNIQUE KEY uk_trend_exit_intent_client(client_order_id),KEY idx_trend_exit_intent_pending(status,updated_at),KEY idx_trend_exit_intent_position(position_id,position_epoch));
CREATE TABLE htx_trend_exit_fill_v5 (id BIGINT AUTO_INCREMENT PRIMARY KEY,intent_id BIGINT NOT NULL,account_id BIGINT NOT NULL,exchange_order_id VARCHAR(64) NOT NULL,trade_id VARCHAR(128) NOT NULL,filled_qty DECIMAL(36,18) NOT NULL,fill_price DECIMAL(36,18) NOT NULL,fee DECIMAL(36,18) NOT NULL,allocated_entry_fee DECIMAL(36,18) NOT NULL,allocated_funding DECIMAL(36,18) NOT NULL,filled_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uk_trend_exit_fill_trade(account_id,trade_id));
CREATE TABLE htx_trend_reentry_guard_v5 (guard_key CHAR(64) PRIMARY KEY,account_id BIGINT NOT NULL,strategy_family VARCHAR(32) NOT NULL,contract_code VARCHAR(32) NOT NULL,side VARCHAR(8) NOT NULL,structure_id VARCHAR(160) NOT NULL,revision BIGINT NOT NULL,same_structure_attempts INT NOT NULL DEFAULT 0,accumulated_realized_loss DECIMAL(36,18) NOT NULL DEFAULT 0,accumulated_fees DECIMAL(36,18) NOT NULL DEFAULT 0,exit_reason VARCHAR(64) NOT NULL,status VARCHAR(24) NOT NULL,evidence_json MEDIUMTEXT NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY idx_trend_reentry_scope(account_id,contract_code,side,status));
